          nerr("ERROR: Send failed: %d\n", ret);
          arp_wait_cancel(notify);
          break;
        }

      /* Now wait for response to the ARP response to be received. */

wait:
      ret = arp_wait(dev, notify, CONFIG_ARP_SEND_DELAYMSEC);

