           ip4_addr1(ipaddr), ip4_addr2(ipaddr),
           ip4_addr3(ipaddr), ip4_addr4(ipaddr));
    }

  nxsem_destroy(&state->snd_sem);
  arp_callback_free(dev, state->snd_cb);
  netdev_unlock(dev);
  mempool_release(&g_arp_send_infos, info);
  return ret;
}

